# signature-ci — valida la FORMA de los PRs de firma (corre CON o SIN Ledger Bot).
# Destino: .github/workflows/signature-ci.yml
# v2.2 (final): el firmante SOLO añade 1 línea al FINAL (un guion o su
# frase). Cero formato que validar: 1 línea añadida / 0 borradas / solo
# SIGNATURES.md / al final del fichero / ≤200 chars / sin bidi/zero-width.
# La identidad es ESTRUCTURAL (autor del PR) — la línea canónica la escribe el bot.
name: signature-ci
on:
  pull_request:
    paths: [SIGNATURES.md]

permissions:
  contents: read
  pull-requests: write

concurrency:
  group: signature-ci-${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  validate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v7
        with: { fetch-depth: 0 }
      - name: Validate diff shape + line format
        id: check
        env:
          PR_AUTHOR: ${{ github.event.pull_request.user.login }}
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
        run: |
          set -euo pipefail
          # Solo SIGNATURES.md puede cambiar
          CHANGED=$(git diff --name-only "$BASE_SHA...$HEAD_SHA")
          [ "$CHANGED" = "SIGNATURES.md" ] || { echo "reason=Only SIGNATURES.md may change in a signature PR (changed: $CHANGED)" >> "$GITHUB_OUTPUT"; exit 1; }
          # Exactamente +1/-0
          read -r ADD DEL _ <<< "$(git diff --numstat "$BASE_SHA...$HEAD_SHA" -- SIGNATURES.md)"
          [ "$ADD" = "1" ] && [ "$DEL" = "0" ] || { echo "reason=Signature PRs add exactly 1 line and remove 0 (got +$ADD/-$DEL)" >> "$GITHUB_OUTPUT"; exit 1; }
          LINE=$(git diff "$BASE_SHA...$HEAD_SHA" -- SIGNATURES.md | grep '^+' | grep -v '^+++' | sed 's/^+//')
          # v2.2: la línea debe estar AL FINAL del fichero
          LAST=$(tail -n 1 SIGNATURES.md)
          [ "$LINE" = "$LAST" ] || { echo "reason=Your line must be the LAST line of SIGNATURES.md — move it to the very end" >> "$GITHUB_OUTPUT"; exit 1; }
          printf '%s' "$LINE" > /tmp/sig-line.txt
          node --input-type=module -e '
            import { readFileSync } from "node:fs";
            const raw = readFileSync("/tmp/sig-line.txt", "utf8");
            const line = raw.normalize("NFC");
            // bidi / zero-width / control codepoints prohibidos
            if (/[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF\u0000-\u0008\u000B-\u001F]/u.test(line)) {
              console.error("reason=Line contains invisible/bidi control characters"); process.exit(1);
            }
            if (line.length > 200) { console.error("reason=Keep it to one sentence (max 200 characters)"); process.exit(1); }
            // v2.2: NADA más que validar — la identidad es el autor del PR (estructural);
            // el contenido se trata SOLO como frase opcional (el bot sanitiza y reescribe
            // la línea canónica desde metadatos — nadie imputa identidad por contenido).
            console.log("shape OK");
          ' 2> /tmp/reason.txt || { cat /tmp/reason.txt >> "$GITHUB_OUTPUT"; exit 1; }
      - name: Friendly ack (valid)
        if: success()
        # Fork PRs carry a read-only token, so this comment can fail with
        # 'Resource not accessible by integration'. The comment is cosmetic:
        # its failure must never turn a VALID signature's check red (30-jul,
        # first fork-signature #2311 sat blocked on exactly this).
        continue-on-error: true
        uses: actions/github-script@v9
        with:
          script: |
            const login = context.payload.pull_request.user.login;
            await github.rest.issues.createComment({
              ...context.repo, issue_number: context.payload.pull_request.number,
              body: `Format valid. You're in the queue — signatures land in waves. Your line will live at https://career-ops.org/manifesto/s/${login}\n\nIf GitHub reports a merge conflict, do nothing; we handle it.`
            });
      - name: Friendly fix-it (invalid)
        if: failure()
        continue-on-error: true
        uses: actions/github-script@v9
        with:
          script: |
            const login = context.payload.pull_request.user.login;
            const reason = `${{ steps.check.outputs.reason || 'the diff shape or line format is off' }}`;
            await github.rest.issues.createComment({
              ...context.repo, issue_number: context.payload.pull_request.number,
              body: `Almost there — ${reason}.\n\nAdd exactly ONE line at the very END of SIGNATURES.md: one sentence about your search (or what you want hiring to become), or just a dash:\n\n\`\`\`\n-\n\`\`\`\n\nYour username, the date and the id are added automatically when your signature lands. No other file or line should change.`
            });

#!/usr/bin/env node

/**
 * agent-inbox-tests.mjs — regression tests for agent-inbox.mjs.
 *
 * Locks in the queue's behaviour:
 *   1. A first `add` seeds the header + agent protocol and one pending item.
 *   2. `add` is append-only and multiline text collapses to a single bullet.
 *   3. `list` shows pending only; `list --all` shows resolved items too.
 *   4. `resolve N` ticks the N-th *pending* item and appends a one-line result,
 *      so `list` then `resolve N` line up.
 *   5. An empty `add` fails loudly (exit 1) rather than queuing a blank line.
 *   6. On the default path, a first `add` self-heals .gitignore (idempotent) so
 *      the personal queue isn't accidentally tracked.
 *
 * Provisions a throwaway queue via CAREER_OPS_INBOX and a temp CWD; never
 * touches real user data.
 */

import { execFileSync } from 'child_process';
import { readFileSync, writeFileSync, mkdtempSync } from 'fs';
import { join, dirname } from 'path';
import { tmpdir } from 'os';
import { fileURLToPath } from 'url';

const ROOT = dirname(fileURLToPath(import.meta.url));
const NODE = process.execPath;
const CLI = join(ROOT, 'agent-inbox.mjs');

let passed = 0;
let failed = 0;
function check(name, cond, detail = '') {
  if (cond) { passed++; console.log(`  ✅ ${name}`); }
  else { failed++; console.log(`  ❌ ${name}${detail ? ` — ${detail}` : ''}`); }
}

function tmp(prefix) {
  return mkdtempSync(join(tmpdir(), prefix));
}

// Run agent-inbox.mjs against a provisioned queue file; returns stdout.
function run(inbox, args, opts = {}) {
  return execFileSync(NODE, [CLI, ...args], {
    cwd: ROOT,
    env: { ...process.env, CAREER_OPS_INBOX: inbox },
    encoding: 'utf8',
    stdio: ['pipe', 'pipe', 'pipe'],
    ...opts,
  });
}

// ---------------------------------------------------------------------------
console.log('1. First add seeds header + protocol and one pending item');
{
  const inbox = join(tmp('inbox-'), 'agent-inbox.md');
  run(inbox, ['add', 'evaluate https://acme.com/jobs/42']);
  const md = readFileSync(inbox, 'utf8');
  check('header present', /^# Agent Inbox/.test(md));
  check('agent protocol documented', /Agent protocol:/.test(md));
  check('nothing auto-submits is stated', /auto-submit/.test(md));
  check('one pending checklist item', (md.match(/^- \[ \]/gm) || []).length === 1, md);
  check('request text preserved', md.includes('evaluate https://acme.com/jobs/42'));
}

// ---------------------------------------------------------------------------
console.log('2. add is append-only; multiline text collapses to one bullet');
{
  const inbox = join(tmp('inbox-'), 'agent-inbox.md');
  run(inbox, ['add', 'first request']);
  run(inbox, ['add', 'second\nrequest with newline']);
  const md = readFileSync(inbox, 'utf8');
  check('two pending items', (md.match(/^- \[ \]/gm) || []).length === 2);
  check('first item retained', md.includes('first request'));
  check('newline collapsed (no mid-item break)', md.includes('second request with newline'));
  check('item count == bullet count (no stray bullets)', (md.match(/^- \[/gm) || []).length === 2);
}

// ---------------------------------------------------------------------------
console.log('3. list shows pending; --all includes resolved');
{
  const inbox = join(tmp('inbox-'), 'agent-inbox.md');
  run(inbox, ['add', 'alpha']);
  run(inbox, ['add', 'beta']);
  run(inbox, ['resolve', '1', '--result', 'done alpha']);
  const pending = run(inbox, ['list']);
  const all = run(inbox, ['list', '--all']);
  check('pending list hides resolved alpha', !pending.includes('alpha') && pending.includes('beta'), pending.trim());
  check('--all shows both', all.includes('alpha') && all.includes('beta'));
}

// ---------------------------------------------------------------------------
console.log('4. resolve ticks the N-th pending item + appends a one-line result');
{
  const inbox = join(tmp('inbox-'), 'agent-inbox.md');
  run(inbox, ['add', 'gamma']);
  run(inbox, ['resolve', '1', '--result', 'scored 4.3 — report 012']);
  const md = readFileSync(inbox, 'utf8');
  check('item marked done', /^- \[x\] .*gamma/m.test(md), md);
  check('result appended', /→ result: scored 4\.3 — report 012/.test(md));
  check('no pending left', (md.match(/^- \[ \]/gm) || []).length === 0);
}

// ---------------------------------------------------------------------------
console.log('5. empty add fails (exit 1), does not queue a blank line');
{
  const inbox = join(tmp('inbox-'), 'agent-inbox.md');
  let exit = 0;
  try { run(inbox, ['add', '   ']); } catch (e) { exit = e.status; }
  check('non-zero exit on empty request', exit === 1, `exit=${exit}`);
}

// ---------------------------------------------------------------------------
console.log('6. first add on the default path self-heals .gitignore (idempotent)');
{
  const repo = tmp('inbox-repo-');
  writeFileSync(join(repo, '.gitignore'), 'node_modules\noutput/*\n');
  const addOnce = () => execFileSync(NODE, [CLI, 'add', 'queue a scan'], {
    cwd: repo, env: { ...process.env, CAREER_OPS_INBOX: '' }, stdio: ['pipe', 'pipe', 'pipe'],
  });
  addOnce(); addOnce();
  const gi = readFileSync(join(repo, '.gitignore'), 'utf8');
  const ruleCount = gi.split('\n').filter((l) => l.trim() === 'data/agent-inbox.md').length;
  check('.gitignore gains exactly one data/agent-inbox.md rule', ruleCount === 1, `count=${ruleCount}`);
}

console.log(`\nResults: ${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);

// tests/browser-extract.test.mjs — unit coverage for the pure logic in
// browser-extract.mjs (config resolution + result normalizers). The Playwright
// navigation path is exercised live, not here.
import { pass, fail, ROOT } from './helpers.mjs';
import { join } from 'path';
import { pathToFileURL } from 'url';
import { mkdtempSync, writeFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';

console.log('\nbrowser-extract.mjs (config + normalizers)');

try {
  const mod = await import(pathToFileURL(join(ROOT, 'browser-extract.mjs')).href);
  const { resolveExtractorMode, compactText, normalizeJd, normalizeListing, parseArgs } = mod;

  // resolveExtractorMode — default mcp, explicit cli, garbage → mcp, missing → mcp
  const tmp = mkdtempSync(join(tmpdir(), 'career-ops-extractor-'));
  try {
    const write = (name, body) => { const p = join(tmp, name); writeFileSync(p, body); return p; };
    if (resolveExtractorMode(write('cli.yml', 'scan:\n  extractor: cli\n')) === 'cli') pass('resolveExtractorMode reads scan.extractor: cli');
    else fail('resolveExtractorMode should read cli');
    if (resolveExtractorMode(write('mcp.yml', 'scan:\n  extractor: mcp\n')) === 'mcp') pass('resolveExtractorMode reads scan.extractor: mcp');
    else fail('resolveExtractorMode should read mcp');
    if (resolveExtractorMode(write('none.yml', 'candidate:\n  full_name: X\n')) === 'mcp') pass('resolveExtractorMode defaults to mcp when the key is absent');
    else fail('resolveExtractorMode should default to mcp');
    if (resolveExtractorMode(write('bad.yml', 'scan:\n  extractor: nonsense\n')) === 'mcp') pass('resolveExtractorMode falls back to mcp for an unknown value');
    else fail('resolveExtractorMode should fall back to mcp on garbage');
    if (resolveExtractorMode(join(tmp, 'does-not-exist.yml')) === 'mcp') pass('resolveExtractorMode returns mcp when the profile is missing');
    else fail('resolveExtractorMode should return mcp for a missing file');
    if (resolveExtractorMode(write('malformed.yml', 'scan:\n  extractor: [cli\n')) === 'mcp') pass('resolveExtractorMode falls back to mcp on malformed YAML (catch branch)');
    else fail('resolveExtractorMode should return mcp when the YAML is invalid');
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }

  // parseArgs — index-based: a flag value is never mistaken for the URL, and 0 is honored
  const flagsFirst = parseArgs(['--mode', 'listing', 'https://x/careers']);
  if (flagsFirst.url === 'https://x/careers' && flagsFirst.mode === 'listing') pass('parseArgs finds the URL even when flags precede it');
  else fail(`parseArgs flags-first => ${JSON.stringify(flagsFirst)}`);
  const urlFirst = parseArgs(['https://x/1', '--mode', 'jd', '--max', '5']);
  if (urlFirst.url === 'https://x/1' && urlFirst.mode === 'jd' && urlFirst.max === 5) pass('parseArgs handles url-first with flags');
  else fail(`parseArgs url-first => ${JSON.stringify(urlFirst)}`);
  const zeroMax = parseArgs(['https://x/1', '--max', '0']);
  if (zeroMax.max === 0) pass('parseArgs honors --max 0 (not silently replaced by the default)');
  else fail(`parseArgs --max 0 => ${zeroMax.max}`);
  const badMax = parseArgs(['https://x/1', '--max', 'abc']);
  if (badMax.max === 200) pass('parseArgs falls back to the default for a non-integer --max');
  else fail(`parseArgs --max abc => ${badMax.max}`);

  // parseArgs --max-chars (#configurable JD cap): overrides the jd text cap,
  // defaults to 12000, and rejects non-positive/non-integer values.
  if (parseArgs(['https://x/1']).maxChars === 12000) pass('parseArgs defaults maxChars to the 12000 JD cap');
  else fail(`parseArgs default maxChars => ${parseArgs(['https://x/1']).maxChars}`);
  const bigChars = parseArgs(['https://x/1', '--max-chars', '40000']);
  if (bigChars.maxChars === 40000) pass('parseArgs honors an explicit --max-chars');
  else fail(`parseArgs --max-chars 40000 => ${bigChars.maxChars}`);
  const badChars = parseArgs(['https://x/1', '--max-chars', '0']);
  if (badChars.maxChars === 12000) pass('parseArgs ignores a non-positive --max-chars (keeps the default cap)');
  else fail(`parseArgs --max-chars 0 => ${badChars.maxChars}`);
  const nonIntChars = parseArgs(['https://x/1', '--max-chars', '1.5']);
  if (nonIntChars.maxChars === 12000) pass('parseArgs ignores a non-integer --max-chars (keeps the default cap)');
  else fail(`parseArgs --max-chars 1.5 => ${nonIntChars.maxChars}`);

  // compactText — collapse whitespace + cap length
  if (compactText('a   b\t\tc') === 'a b c') pass('compactText collapses runs of whitespace');
  else fail(`compactText => ${JSON.stringify(compactText('a   b\t\tc'))}`);
  const capped = compactText('x'.repeat(50), 10);
  if (capped.length === 11 && capped.endsWith('…')) pass('compactText caps length and appends an ellipsis');
  else fail(`compactText cap => ${JSON.stringify(capped)}`);

  // normalizeJd — shape { url, title, text }
  const jd = normalizeJd({ title: '  Senior Go  Engineer ', text: 'Line1\n\n\n\nLine2   end' }, 'https://x/1');
  if (jd.url === 'https://x/1' && jd.title === 'Senior Go Engineer' && jd.text === 'Line1\n\nLine2 end') {
    pass('normalizeJd shapes { url, title, text } and compacts both');
  } else {
    fail(`normalizeJd => ${JSON.stringify(jd)}`);
  }

  // normalizeJd honors a custom text cap (a long JD is truncated at the cap, not
  // silently at the 12000 default) while leaving the default behavior unchanged.
  const longText = 'y'.repeat(20000);
  const raised = normalizeJd({ title: 'Role', text: longText }, 'https://x/1', 15000);
  const defaulted = normalizeJd({ title: 'Role', text: longText }, 'https://x/1');
  if (raised.text.length === 15001 && raised.text.endsWith('…') &&
      defaulted.text.length === 12001 && defaulted.text.endsWith('…')) {
    pass('normalizeJd applies a custom textCap and defaults to the 12000 JD cap');
  } else {
    fail(`normalizeJd textCap => raised=${raised.text.length} default=${defaulted.text.length}`);
  }

  // normalizeListing — resolve relatives, drop nav/short labels, dedup, cap
  const anchors = [
    { href: '/jobs/1', label: 'Staff Engineer' },
    { href: 'https://x/jobs/1', label: 'Staff Engineer (dupe URL after resolve)' }, // different label, but…
    { href: '/jobs/2', label: 'Careers' },       // nav stopword → dropped
    { href: '/jobs/3', label: 'AI' },             // too short → dropped
    { href: 'javascript:void(0)', label: 'Broken Protocol Role' }, // non-http → dropped
    { href: '/jobs/4', label: 'ML Platform Lead' },
  ];
  const listed = normalizeListing(anchors, 'https://x/careers', 10);
  const urls = listed.jobs.map((j) => j.url);
  if (listed.url === 'https://x/careers' &&
      listed.jobs.length === 2 &&
      urls.includes('https://x/jobs/1') && urls.includes('https://x/jobs/4') &&
      listed.jobs[0].title === 'Staff Engineer') {
    pass('normalizeListing resolves relative URLs, dedups, drops nav/short/non-http anchors');
  } else {
    fail(`normalizeListing => ${JSON.stringify(listed.jobs)}`);
  }

  // dedup by resolved URL
  const dup = normalizeListing(
    [{ href: '/j/1', label: 'Role A' }, { href: 'https://x/j/1', label: 'Role A again' }],
    'https://x/careers',
  );
  if (dup.jobs.length === 1) pass('normalizeListing dedups by resolved URL');
  else fail(`normalizeListing dedup => ${JSON.stringify(dup.jobs)}`);

  // max cap
  const many = normalizeListing(
    Array.from({ length: 20 }, (_, i) => ({ href: `/j/${i}`, label: `Role Number ${i}` })),
    'https://x/careers',
    5,
  );
  if (many.jobs.length === 5) pass('normalizeListing respects the max cap');
  else fail(`normalizeListing max => ${many.jobs.length}`);

} catch (e) {
  fail(`browser-extract tests crashed: ${e.message}`);
}

// tests/playwright-mcp-detection.test.mjs — CLI-aware Playwright MCP detection
// coverage in `doctor.mjs`. CLI resolution precedence lives in
// tests/doctor-cli-resolution.test.mjs; this file owns the resolution × MCP
// coupling. See plan/opencode-json-ignore.md for context.
// Each scenario uses a fresh --target dir so no MCP config leaks across cases.
import { pass, fail, NODE, ROOT } from './helpers.mjs';
import { execFileSync } from 'child_process';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';

console.log('\ndoctor.mjs — CLI-aware Playwright MCP detection');

const DOCTOR = join(ROOT, 'doctor.mjs');

function runDoctor(cwd, args, env) {
  try {
    const out = execFileSync(NODE, [DOCTOR, '--json', '--target', cwd, ...args], {
      cwd,
      env: { ...process.env, ...env },
      encoding: 'utf-8',
      stdio: ['ignore', 'pipe', 'pipe'],
    }).trim();
    return JSON.parse(out);
  } catch (e) {
    return { _error: e.message, _stderr: e.stderr ? String(e.stderr) : '' };
  }
}

function expectWarn(state, msg) {
  if (state._error) { fail(`${msg}: doctor crashed: ${state._error}`); return false; }
  return true;
}

const PLAYWRIGHT_RE = /playwright mcp/i;

try {
  // 1. Default CLI (no flag/env/.env), no MCP config anywhere → warning fires.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-1-'));
    try {
      const state = runDoctor(dir, [], {});
      if (!expectWarn(state, '#1 default CLI no config')) {
        // already failed
      } else if (state.active_cli === 'claude'
          && state.cli_source === 'default'
          && state.playwright_mcp?.claude === false
          && Array.isArray(state.warnings)
          && state.warnings.some((w) => PLAYWRIGHT_RE.test(w) && /active cli: claude/i.test(w))) {
        pass('default CLI + no config → warning fires with default-CLI label');
      } else {
        fail(`#1 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 2. .claude/settings.json has Playwright, default CLI is claude → no warning.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-2-'));
    try {
      mkdirSync(join(dir, '.claude'), { recursive: true });
      writeFileSync(join(dir, '.claude', 'settings.json'),
        JSON.stringify({ mcpServers: { playwright: { command: 'npx', args: ['@playwright/mcp'] } } }));
      const state = runDoctor(dir, [], {});
      if (!expectWarn(state, '#2 default CLI with Claude config')) {
        // already failed
      } else if (state.active_cli === 'claude'
          && state.cli_source === 'default'
          && state.playwright_mcp?.claude === true
          && Array.isArray(state.warnings)
          && !state.warnings.some((w) => PLAYWRIGHT_RE.test(w))) {
        pass('default CLI + Claude config → no warning');
      } else {
        fail(`#2 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 3. --cli opencode + opencode.json with Playwright → no warning; source=flag.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-3-'));
    try {
      writeFileSync(join(dir, 'opencode.json'),
        JSON.stringify({ mcp: { playwright: { type: 'local', command: ['npx', '-y', '@playwright/mcp@latest'] } } }));
      const state = runDoctor(dir, ['--cli', 'opencode'], {});
      if (!expectWarn(state, '#3 --cli opencode with config')) {
        // already failed
      } else if (state.active_cli === 'opencode'
          && state.cli_source === 'flag'
          && state.playwright_mcp?.opencode === true
          && Array.isArray(state.warnings)
          && !state.warnings.some((w) => PLAYWRIGHT_RE.test(w))) {
        pass('--cli opencode + opencode.json → no warning (cli_source=flag)');
      } else {
        fail(`#3 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 4. --cli opencode, no opencode.json → warning with active-CLI label.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-4-'));
    try {
      const state = runDoctor(dir, ['--cli', 'opencode'], {});
      if (!expectWarn(state, '#4 --cli opencode without config')) {
        // already failed
      } else if (state.active_cli === 'opencode'
          && state.cli_source === 'flag'
          && state.playwright_mcp?.opencode === false
          && Array.isArray(state.warnings)
          && state.warnings.some((w) => PLAYWRIGHT_RE.test(w) && /active cli: opencode/i.test(w))) {
        pass('--cli opencode without config → warning has active-CLI label');
      } else {
        fail(`#4 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 5. CAREER_OPS_CLI=opencode via env (no flag, no .env), no opencode.json.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-5-'));
    try {
      const state = runDoctor(dir, [], { CAREER_OPS_CLI: 'opencode' });
      if (!expectWarn(state, '#5 env=opencode')) {
        // already failed
      } else if (state.active_cli === 'opencode'
          && state.cli_source === 'env'
          && state.playwright_mcp?.opencode === false
          && Array.isArray(state.warnings)
          && state.warnings.some((w) => PLAYWRIGHT_RE.test(w) && /active cli: opencode/i.test(w))) {
        pass('CAREER_OPS_CLI env + no config → warning, cli_source=env');
      } else {
        fail(`#5 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 6. .env in --target has CAREER_OPS_CLI=opencode, process.env unset.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-6-'));
    try {
      writeFileSync(join(dir, '.env'), 'CAREER_OPS_CLI=opencode\n');
      const state = runDoctor(dir, [], {});  // no env override
      if (!expectWarn(state, '#6 .env=opencode')) {
        // already failed
      } else if (state.active_cli === 'opencode'
          && state.cli_source === '.env'
          && state.playwright_mcp?.opencode === false
          && Array.isArray(state.warnings)
          && state.warnings.some((w) => PLAYWRIGHT_RE.test(w))) {
        pass('.env file with CAREER_OPS_CLI → cli_source=.env, warning fires');
      } else {
        fail(`#6 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 7. Both .claude/settings.json and opencode.json have Playwright, no flag/env/.env.
  //    Default Claude is configured → doctor does NOT consult OpenCode → no warning.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-7-'));
    try {
      mkdirSync(join(dir, '.claude'), { recursive: true });
      writeFileSync(join(dir, '.claude', 'settings.json'),
        JSON.stringify({ mcpServers: { playwright: { command: 'npx', args: ['@playwright/mcp'] } } }));
      writeFileSync(join(dir, 'opencode.json'),
        JSON.stringify({ mcp: { playwright: { type: 'local' } } }));
      const state = runDoctor(dir, [], {});
      if (!expectWarn(state, '#7 dual config + default CLI')) {
        // already failed
      } else if (state.active_cli === 'claude'
          && state.cli_source === 'default'
          && state.playwright_mcp?.claude === true
          && typeof state.playwright_mcp?.opencode === 'undefined'
          && Array.isArray(state.warnings)
          && !state.warnings.some((w) => PLAYWRIGHT_RE.test(w))) {
        pass('default CLI + Claude config suppresses warning even when opencode.json is present');
      } else {
        fail(`#7 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 8. --cli opencode with only .claude/settings.json present. The active CLI is
  //    opencode; Claude config is irrelevant → warning fires.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-8-'));
    try {
      mkdirSync(join(dir, '.claude'), { recursive: true });
      writeFileSync(join(dir, '.claude', 'settings.json'),
        JSON.stringify({ mcpServers: { playwright: { command: 'npx', args: ['@playwright/mcp'] } } }));
      const state = runDoctor(dir, ['--cli', 'opencode'], {});
      if (!expectWarn(state, '#8 --cli opencode with only Claude config')) {
        // already failed
      } else if (state.active_cli === 'opencode'
          && state.cli_source === 'flag'
          && state.playwright_mcp?.opencode === false
          && Array.isArray(state.warnings)
          && state.warnings.some((w) => PLAYWRIGHT_RE.test(w) && /active cli: opencode/i.test(w))) {
        pass('--cli opencode with only Claude config → warning (Claude config is irrelevant)');
      } else {
        fail(`#8 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 9. --cli codex → known CLI without MCP scanner; warn (case B).
  //    active_cli is preserved verbatim ("codex"), cli_source='flag',
  //    playwright_mcp is {} (not claude), and the "skipped for CLI: codex"
  //    warning fires — distinct from case A (unknown CLI), which is silent.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-9-'));
    try {
      const state = runDoctor(dir, ['--cli', 'codex'], {});
      if (state._error) { fail(`#9 doctor crashed: ${state._error}`); }
      else if (state.active_cli === 'codex'
          && state.cli_source === 'flag'
          && Object.keys(state.playwright_mcp || {}).length === 0
          && Array.isArray(state.warnings)
          && state.warnings.some((w) => /Playwright MCP check skipped for CLI: codex/i.test(w))) {
        pass('--cli codex → known but unsupported, warn "skipped for CLI: codex"');
      } else {
        fail(`#9 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 10. --cli vim (typo) → resolveActiveCli returns cli='unknown', source='flag'
  //     and emits one warning naming the bad value. MCP check is silent (the
  //     CLI-resolution layer already warned; MCP has nothing to add).
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-10-'));
    try {
      const state = runDoctor(dir, ['--cli', 'vim'], {});
      if (state._error) { fail(`#10 doctor crashed: ${state._error}`); }
      else if (state.active_cli === 'unknown'
          && state.cli_source === 'flag'
          && Object.keys(state.playwright_mcp || {}).length === 0
          && Array.isArray(state.warnings)
          && state.warnings.length === 1
          && /Unknown --cli "vim"/.test(state.warnings[0])) {
        pass('--cli vim → unknown sentinel, one warning naming the bad value');
      } else {
        fail(`#10 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 11. CAREER_OPS_CLI=vim (invalid env) → same as #10 but via env path.
  //     active_cli='unknown', cli_source='env', one warning with the env path.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-11-'));
    try {
      const state = runDoctor(dir, [], { CAREER_OPS_CLI: 'vim' });
      if (state._error) { fail(`#11 doctor crashed: ${state._error}`); }
      else if (state.active_cli === 'unknown'
          && state.cli_source === 'env'
          && Object.keys(state.playwright_mcp || {}).length === 0
          && Array.isArray(state.warnings)
          && state.warnings.length === 1
          && /CAREER_OPS_CLI="vim"/.test(state.warnings[0])) {
        pass('CAREER_OPS_CLI="vim" (invalid) → unknown sentinel, one warning via env path');
      } else {
        fail(`#11 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 12. Pin the warnings[] entry format for the (default-CLI) Playwright MCP
  //     warning so any future text edit fails loudly instead of silently
  //     breaking downstream consumers that key off the prefix/structure.
  //     The format change (Issue #3 in the OpenCode PR review) is a public
  //     contract; this regression test guards it.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-12-'));
    try {
      const state = runDoctor(dir, [], {});
      const mcpWarn = Array.isArray(state.warnings)
        ? state.warnings.find((w) => PLAYWRIGHT_RE.test(w))
        : null;
      if (!mcpWarn) {
        fail('#12 expected a Playwright MCP warning to pin its format');
      } else if (/^Playwright MCP tools not detected \(active CLI: claude\)\n→ /.test(mcpWarn)) {
        pass('warnings[] MCP entry format pinned (label + newline + arrow + hint)');
      } else {
        fail(`#12 unexpected warning format: ${JSON.stringify(mcpWarn)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 13. opencode.json with Playwright under the `mcp` bucket, --cli opencode:
  //     no warning. Pins that the opencode CLI's MCP files are scanned.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-13-'));
    try {
      writeFileSync(join(dir, 'opencode.json'),
        JSON.stringify({ mcp: { playwright: { type: 'local', command: ['npx', '-y', '@playwright/mcp'] } } }));
      const state = runDoctor(dir, ['--cli', 'opencode'], {});
      if (!expectWarn(state, '#13 --cli opencode with .json config')) {
        // already failed
      } else if (state.active_cli === 'opencode'
          && state.cli_source === 'flag'
          && state.playwright_mcp?.opencode === true
          && Array.isArray(state.warnings)
          && !state.warnings.some((w) => PLAYWRIGHT_RE.test(w))) {
        pass('--cli opencode + opencode.json → no warning');
      } else {
        fail(`#13 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

  // 14. Both `mcpServers` and `mcp` buckets in the same config are unioned.
  //     `mcpServers` is empty (would early-return false on its own), `mcp`
  //     carries the Playwright server. If a future edit changes the bucket
  //     scan to short-circuit on the first non-empty bucket, the opencode-style
  //     `mcp` entry would be silently skipped.
  {
    const dir = mkdtempSync(join(tmpdir(), 'co-mcp-14-'));
    try {
      mkdirSync(join(dir, '.claude'), { recursive: true });
      writeFileSync(join(dir, '.claude', 'settings.json'),
        JSON.stringify({ mcpServers: {}, mcp: { playwright: { type: 'local', command: ['npx', '-y', '@playwright/mcp'] } } }));
      const state = runDoctor(dir, [], {});
      if (!expectWarn(state, '#14 dual bucket union')) {
        // already failed
      } else if (state.active_cli === 'claude'
          && state.cli_source === 'default'
          && state.playwright_mcp?.claude === true
          && Array.isArray(state.warnings)
          && !state.warnings.some((w) => PLAYWRIGHT_RE.test(w))) {
        pass('dual bucket (empty mcpServers + populated mcp) is unioned → no warning');
      } else {
        fail(`#14 unexpected state: ${JSON.stringify(state)}`);
      }
    } finally { rmSync(dir, { recursive: true, force: true }); }
  }

} catch (e) {
  fail(`opencode-mcp-detection tests crashed: ${e.message}`);
}

// tests/providers/arbeitsagentur.test.mjs — moved verbatim from test-all.mjs (#1440).
import { pass, fail, ROOT } from '../helpers.mjs';
import { join } from 'path';
import { pathToFileURL } from 'url';

console.log('\nProvider — arbeitsagentur');

try {
  const arbeitsagenturModule = await import(pathToFileURL(join(ROOT, 'providers/arbeitsagentur.mjs')).href);
  const aa = arbeitsagenturModule.default;
  const { parseArbeitsagenturConfig, buildLocation, normalizeJob } = arbeitsagenturModule;

  if (aa.id === 'arbeitsagentur') pass('arbeitsagentur.id is "arbeitsagentur"');
  else fail(`arbeitsagentur.id is ${JSON.stringify(aa.id)}`);

  // parseArbeitsagenturConfig — defaults when block is absent
  const def = parseArbeitsagenturConfig({});
  if (def.keywords.length === 0 && def.wo === '' && def.umkreis === 50 && def.days === 30 && def.size === 100 && def.remoteNationwide === false) {
    pass('parseArbeitsagenturConfig applies defaults (umkreis 50, days 30, size 100)');
  } else {
    fail(`parseArbeitsagenturConfig defaults = ${JSON.stringify(def)}`);
  }

  // parseArbeitsagenturConfig — sanitizes keywords and clamps numbers
  const cfg = parseArbeitsagenturConfig({
    arbeitsagentur: { keywords: ['  ML Engineer  ', '', 7, 'NLP'], wo: ' Berlin ', umkreis: 999999, size: 0, days: -3, remoteNationwide: 'yes' },
  });
  if (cfg.keywords.length === 2 && cfg.keywords[0] === 'ML Engineer' && cfg.keywords[1] === 'NLP') {
    pass('parseArbeitsagenturConfig trims keywords and drops empty/non-string entries');
  } else {
    fail(`parseArbeitsagenturConfig keywords = ${JSON.stringify(cfg.keywords)}`);
  }
  if (cfg.wo === 'Berlin' && cfg.umkreis === 1000 && cfg.size === 1 && cfg.days === 1 && cfg.remoteNationwide === false) {
    pass('parseArbeitsagenturConfig clamps umkreis/size/days and treats non-true remoteNationwide as false');
  } else {
    fail(`parseArbeitsagenturConfig sanitized = ${JSON.stringify(cfg)}`);
  }

  // buildLocation — ort/region join, non-DE country appended, DE omitted
  if (buildLocation({ ort: 'Berlin', region: 'Berlin', land: 'Deutschland' }) === 'Berlin, Berlin') {
    pass('buildLocation joins ort/region and omits Germany');
  } else {
    fail(`buildLocation DE = ${JSON.stringify(buildLocation({ ort: 'Berlin', region: 'Berlin', land: 'Deutschland' }))}`);
  }
  if (buildLocation({ ort: 'Wien', land: 'Österreich' }) === 'Wien, Österreich') {
    pass('buildLocation appends non-DE country');
  } else {
    fail(`buildLocation non-DE = ${JSON.stringify(buildLocation({ ort: 'Wien', land: 'Österreich' }))}`);
  }
  if (buildLocation(null) === '' && buildLocation('x') === '') pass('buildLocation returns "" for missing/garbage input');
  else fail('buildLocation should return "" for missing/garbage input');

  // normalizeJob — happy path encodes refnr into the detail URL
  const norm = normalizeJob({ refnr: '10000-123/4 X', titel: '  ML Engineer  ', arbeitgeber: ' ACME ', arbeitsort: { ort: 'Berlin' } });
  if (norm && norm.title === 'ML Engineer' && norm.company === 'ACME'
      && norm.url === 'https://www.arbeitsagentur.de/jobsuche/jobdetail/' + encodeURIComponent('10000-123/4 X')
      && norm.refnr === '10000-123/4 X') {
    pass('normalizeJob trims fields and URL-encodes refnr');
  } else {
    fail(`normalizeJob = ${JSON.stringify(norm)}`);
  }
  if (normalizeJob({ titel: 'No refnr' }) === null && normalizeJob({ refnr: 'x', titel: '' }) === null) {
    pass('normalizeJob returns null without a refnr or title');
  } else {
    fail('normalizeJob should return null when refnr or title is missing');
  }

  // fetch() — nationwide single-keyword pass, dedup across keywords, header sent
  let sentApiKey = null;
  const mkCtx = (byWas) => ({
    fetchJson: async (url, opts) => {
      sentApiKey = opts?.headers?.['X-API-Key'] ?? sentApiKey;
      const was = new URL(url).searchParams.get('was');
      return { stellenangebote: byWas[was] || [] };
    },
  });
  const fetched = await aa.fetch(
    { name: 'AA', arbeitsagentur: { keywords: ['ML', 'NLP'] } },
    mkCtx({
      ML: [{ refnr: 'A', titel: 'ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'Berlin' } }],
      NLP: [
        { refnr: 'A', titel: 'ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'Berlin' } }, // dup refnr
        { refnr: 'B', titel: 'NLP Scientist', arbeitgeber: 'Co', arbeitsort: { ort: 'Köln' } },
      ],
    }),
  );
  if (fetched.length === 2 && !('refnr' in fetched[0])) pass('aa.fetch() dedups by refnr and strips refnr from output');
  else fail(`aa.fetch() returned ${JSON.stringify(fetched)}`);
  if (sentApiKey === 'jobboerse-jobsuche') pass('aa.fetch() sends the X-API-Key header');
  else fail(`aa.fetch() X-API-Key = ${JSON.stringify(sentApiKey)}`);

  // fetch() — remoteNationwide pass keeps only remote-titled wide hits
  let calls = 0;
  const remoteFetched = await aa.fetch(
    { name: 'AA', arbeitsagentur: { keywords: ['ML'], wo: 'Berlin', remoteNationwide: true } },
    {
      fetchJson: async (url) => {
        calls++;
        const hasWo = new URL(url).searchParams.has('wo');
        // Pass A (wo set) → local hit; Pass B (no wo) → one remote-titled, one not.
        return hasWo
          ? { stellenangebote: [{ refnr: 'L', titel: 'ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'Berlin' } }] }
          : { stellenangebote: [
              { refnr: 'R', titel: 'ML Engineer (Remote)', arbeitgeber: 'Co', arbeitsort: { ort: 'Hamburg' } },
              { refnr: 'X', titel: 'Onsite ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'Hamburg' } },
            ] };
      },
    },
  );
  if (calls === 2 && remoteFetched.some(j => j.url.endsWith('R')) && !remoteFetched.some(j => j.url.endsWith('X'))) {
    pass('aa.fetch() remoteNationwide keeps remote-titled wide hits and drops onsite ones');
  } else {
    fail(`aa.fetch() remoteNationwide = ${calls} calls, ${JSON.stringify(remoteFetched.map(j => j.url))}`);
  }

  // parseArbeitsagenturConfig — remoteMatch mode + remoteMaxPages (config-driven remote detection)
  const rcfg = parseArbeitsagenturConfig({ arbeitsagentur: { keywords: ['ML'], remoteMatch: 'filter', remoteMaxPages: 50 } });
  if (rcfg.remoteMatch === 'filter' && rcfg.remoteMaxPages === 20) {
    pass('parseArbeitsagenturConfig parses remoteMatch and clamps remoteMaxPages');
  } else {
    fail(`parseArbeitsagenturConfig remoteMatch/maxPages = ${JSON.stringify({ m: rcfg.remoteMatch, p: rcfg.remoteMaxPages })}`);
  }
  const rdef = parseArbeitsagenturConfig({ arbeitsagentur: { keywords: ['ML'], remoteMatch: 'bogus' } });
  if (rdef.remoteMatch === 'title' && rdef.remoteMaxPages === 1) {
    pass('parseArbeitsagenturConfig defaults remoteMatch to "title" and remoteMaxPages to 1');
  } else {
    fail(`parseArbeitsagenturConfig remote defaults = ${JSON.stringify({ m: rdef.remoteMatch, p: rdef.remoteMaxPages })}`);
  }

  // fetch() — remoteMatch:'filter' uses server-side homeoffice filter, paginates, and tags
  // only the candidates the detail endpoint confirms as homeofficetyp VOLLSTAENDIG.
  // `homeoffice=nv_true` also returns NACH_VEREINBARUNG (office-anchored hybrid) roles,
  // which must keep their real city so the commute location_filter still drops them.
  let usedHomeoffice = false;
  const pagesSeen = new Set();
  const detailsSeen = [];
  // R1 München = genuinely remote; R2 Stuttgart = hybrid "nach Absprache"; R3 Köln = lookup fails.
  const HOMEOFFICETYP = { R1: 'VOLLSTAENDIG', R2: 'NACH_VEREINBARUNG' };
  const filterFetched = await aa.fetch(
    { name: 'AA', arbeitsagentur: { keywords: ['ML'], wo: 'Berlin', remoteNationwide: true, remoteMatch: 'filter', remoteMaxPages: 5, size: 2 } },
    {
      fetchJson: async (url) => {
        if (url.includes('/jobdetails/')) {
          const refnr = Buffer.from(url.split('/jobdetails/')[1], 'base64').toString();
          detailsSeen.push(refnr);
          if (!(refnr in HOMEOFFICETYP)) throw new Error('HTTP 404'); // unverifiable → must stay untagged
          return { homeofficetyp: HOMEOFFICETYP[refnr] };
        }
        const sp = new URL(url).searchParams;
        if (sp.has('wo')) {
          return { stellenangebote: [{ refnr: 'L', titel: 'ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'Berlin' } }] };
        }
        usedHomeoffice = usedHomeoffice || sp.get('homeoffice') === 'nv_true';
        pagesSeen.add(sp.get('page'));
        return Number(sp.get('page')) === 1
          ? { stellenangebote: [ // full page (== size) → pagination continues
              { refnr: 'R1', titel: 'ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'München' } },
              { refnr: 'R2', titel: 'ML Scientist', arbeitgeber: 'Co', arbeitsort: { ort: 'Stuttgart' } },
            ] }
          : { stellenangebote: [{ refnr: 'R3', titel: 'NLP Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'Köln' } }] }; // short → stop
      },
    },
  );
  const munich = filterFetched.find(j => j.url.endsWith('R1'));
  const stuttgart = filterFetched.find(j => j.url.endsWith('R2'));
  const koeln = filterFetched.find(j => j.url.endsWith('R3'));
  const TAG = /Deutschlandweit \(Homeoffice\)/;
  if (usedHomeoffice && pagesSeen.has('1') && pagesSeen.has('2') && munich && TAG.test(munich.location)) {
    pass('aa.fetch() remoteMatch:filter sends homeoffice=nv_true, paginates, and tags confirmed VOLLSTAENDIG roles');
  } else {
    fail(`aa.fetch() filter mode = ${JSON.stringify({ usedHomeoffice, pages: [...pagesSeen], munichLoc: munich?.location })}`);
  }
  if (stuttgart && !TAG.test(stuttgart.location) && stuttgart.location === 'Stuttgart') {
    pass('aa.fetch() does not tag NACH_VEREINBARUNG (hybrid) roles as nationwide remote');
  } else {
    fail(`aa.fetch() NACH_VEREINBARUNG role = ${JSON.stringify({ loc: stuttgart?.location })}`);
  }
  if (koeln && !TAG.test(koeln.location) && koeln.location === 'Köln') {
    pass('aa.fetch() leaves a posting untagged when the homeofficetyp lookup fails');
  } else {
    fail(`aa.fetch() unverifiable role = ${JSON.stringify({ loc: koeln?.location })}`);
  }
  if (detailsSeen.length === 3 && ['R1', 'R2', 'R3'].every(r => detailsSeen.includes(r))) {
    pass('aa.fetch() verifies homeofficetyp once per remote candidate');
  } else {
    fail(`aa.fetch() detail lookups = ${JSON.stringify(detailsSeen)}`);
  }

  // fetch() — the detail lookups must stay batched (VERIFY_BATCH = 5). With more
  // candidates than one batch, peak in-flight requests must never exceed the cap,
  // and a duplicate refnr across pagination pages must not cost a second lookup.
  // Both would pass silently under an unbounded Promise.all / an un-deduped list.
  let inFlight = 0;
  let peakInFlight = 0;
  const detailCalls = [];
  const wideRefs = ['W1', 'W2', 'W3', 'W4', 'W5', 'W6', 'W7'];
  const batchFetched = await aa.fetch(
    { name: 'AA', arbeitsagentur: { keywords: ['ML'], wo: 'Berlin', remoteNationwide: true, remoteMatch: 'filter', remoteMaxPages: 5, size: 7 } },
    {
      fetchJson: async (url) => {
        if (url.includes('/jobdetails/')) {
          const refnr = Buffer.from(url.split('/jobdetails/')[1], 'base64').toString();
          detailCalls.push(refnr);
          inFlight++;
          peakInFlight = Math.max(peakInFlight, inFlight);
          await new Promise(r => setTimeout(r, 5)); // hold the slot so overlap is observable
          inFlight--;
          return { homeofficetyp: 'VOLLSTAENDIG' };
        }
        const sp = new URL(url).searchParams;
        if (sp.has('wo')) return { stellenangebote: [] };
        // Page 1 is full (== size) so pagination continues; W1 repeats on page 2.
        return Number(sp.get('page')) === 1
          ? { stellenangebote: wideRefs.map(r => ({ refnr: r, titel: 'ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'München' } })) }
          : { stellenangebote: [{ refnr: 'W1', titel: 'ML Engineer', arbeitgeber: 'Co', arbeitsort: { ort: 'München' } }] };
      },
    },
  );
  if (peakInFlight > 0 && peakInFlight <= 5) {
    pass(`aa.fetch() caps concurrent homeofficetyp lookups at VERIFY_BATCH (peak ${peakInFlight})`);
  } else {
    fail(`aa.fetch() peak in-flight detail requests = ${peakInFlight} (expected 1..5)`);
  }
  if (detailCalls.length === wideRefs.length && new Set(detailCalls).size === wideRefs.length) {
    pass('aa.fetch() verifies each duplicated refnr only once');
  } else {
    fail(`aa.fetch() detail calls = ${detailCalls.length} (${JSON.stringify(detailCalls)}), expected ${wideRefs.length} unique`);
  }
  if (batchFetched.length === wideRefs.length && batchFetched.every(j => /Deutschlandweit \(Homeoffice\)/.test(j.location))) {
    pass('aa.fetch() tags every confirmed VOLLSTAENDIG candidate across batches');
  } else {
    fail(`aa.fetch() batched tagging = ${JSON.stringify(batchFetched.map(j => j.location))}`);
  }

  // fetch() — no keywords throws; total outage throws (not silent)
  let noKw = false;
  try { await aa.fetch({ name: 'AA', arbeitsagentur: {} }, mkCtx({})); } catch { noKw = true; }
  if (noKw) pass('aa.fetch() throws when no keywords are configured');
  else fail('aa.fetch() should throw without keywords');

  let outage = false;
  try {
    await aa.fetch({ name: 'AA', arbeitsagentur: { keywords: ['ML'] } }, { fetchJson: async () => { throw new Error('HTTP 503'); } });
  } catch { outage = true; }
  if (outage) pass('aa.fetch() throws when every keyword request fails (no silent empty)');
  else fail('aa.fetch() should throw on total outage');

  // fetch() — one keyword answers (empty) while another fails → NOT a total
  // outage; partial success must not throw.
  let partialThrew = false;
  let partial;
  try {
    partial = await aa.fetch(
      { name: 'AA', arbeitsagentur: { keywords: ['OK', 'BAD'] } },
      { fetchJson: async (url) => {
          if (new URL(url).searchParams.get('was') === 'BAD') throw new Error('HTTP 503');
          return { stellenangebote: [] }; // OK answers, just empty
        } },
    );
  } catch { partialThrew = true; }
  if (!partialThrew && Array.isArray(partial) && partial.length === 0) {
    pass('aa.fetch() does not throw when one keyword succeeds empty and another fails');
  } else {
    fail(`aa.fetch() partial-success threw=${partialThrew}, result=${JSON.stringify(partial)}`);
  }

  // fetch() — Pass A succeeds with jobs, optional Pass B fails → Pass A jobs kept.
  const passBFail = await aa.fetch(
    { name: 'AA', arbeitsagentur: { keywords: ['ML'], wo: 'Berlin', remoteNationwide: true } },
    { fetchJson: async (url) => {
        // Pass A (wo set) returns a job; Pass B (no wo) throws.
        if (new URL(url).searchParams.has('wo')) {
