// tests/providers/dns-pacing.test.mjs — token-bucket pacing for providers/_dns-cache.mjs.
// Fake clock + manual timer: no real waiting, no network, deterministic ordering.
import { pass, fail, ROOT } from '../helpers.mjs';
import { join } from 'path';
import { pathToFileURL } from 'url';

console.log('\nProvider — DNS lookup pacing');

try {
  const { createTokenBucket, createCachedLookup, lookupsPerMinFromEnv } = await import(
    pathToFileURL(join(ROOT, 'providers/_dns-cache.mjs')).href
  );

  /**
   * Manual timer: records what the bucket scheduled instead of waiting for it.
   * `fireAll()` runs everything currently pending — anything the callback
   * schedules in turn lands in the next batch, so a test advances the clock
   * one refill at a time and sees exactly one release per step.
   */
  const mkTimer = () => {
    const timers = [];
    const setTimer = (fn, ms) => { timers.push({ fn, ms }); };
    setTimer.fireAll = () => { for (const t of timers.splice(0)) t.fn(); };
    setTimer.pending = () => timers.length;
    return setTimer;
  };

  // --- a burst up to capacity runs immediately, the rest queues ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const bucket = createTokenBucket({ ratePerMin: 60, capacity: 3, now: () => clock, setTimer });

    const ran = [];
    for (let i = 0; i < 5; i++) bucket.take(() => ran.push(i));
    const immediate = ran.join(',');

    clock += 1_000;                       // 60/min = one token per second
    setTimer.fireAll();
    const afterOne = ran.join(',');

    clock += 1_000;
    setTimer.fireAll();
    const afterTwo = ran.join(',');

    if (immediate === '0,1,2' && afterOne === '0,1,2,3' && afterTwo === '0,1,2,3,4') {
      pass('token bucket admits the burst, then releases one per refill in FIFO order');
    } else {
      fail(`pacing wrong: immediate=[${immediate}] afterOne=[${afterOne}] afterTwo=[${afterTwo}]`);
    }
  }

  // --- an idle bucket refills back to capacity, and no further ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const bucket = createTokenBucket({ ratePerMin: 60, capacity: 3, now: () => clock, setTimer });

    for (let i = 0; i < 3; i++) bucket.take(() => {});   // drain
    clock += 60_000;                                      // idle a full minute
    const ran = [];
    for (let i = 0; i < 5; i++) bucket.take(() => ran.push(i));

    if (ran.join(',') === '0,1,2' && bucket.pending === 2) {
      pass('an idle bucket refills to capacity and is capped there');
    } else {
      fail(`refill cap wrong: ran=[${ran.join(',')}] pending=${bucket.pending}`);
    }
  }

  // --- stats count only the delayed calls, and how long they waited ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const bucket = createTokenBucket({ ratePerMin: 60, capacity: 1, now: () => clock, setTimer });

    bucket.take(() => {});                // immediate — not delayed
    bucket.take(() => {});                // queued
    clock += 1_000;
    setTimer.fireAll();

    const s = bucket.stats();
    if (s.delayed === 1 && s.waitedMs === 1_000) {
      pass('stats report 1 delayed lookup waiting 1000ms');
    } else {
      fail(`stats wrong: delayed=${s.delayed} waitedMs=${s.waitedMs}`);
    }
  }

  // --- a nonsense rate is a caller error, not a silent Infinity ---
  {
    const bad = [];
    for (const rate of [0, -5, Number.NaN]) {
      try { createTokenBucket({ ratePerMin: rate }); bad.push(rate); } catch (e) {
        if (!(e instanceof RangeError)) bad.push(`${rate}:${e.constructor.name}`);
      }
    }
    if (bad.length === 0) {
      pass('createTokenBucket rejects a non-positive or non-finite rate with RangeError');
    } else {
      fail(`bad rates accepted or wrongly typed: ${bad.join(', ')}`);
    }
  }

  // --- a refill delay never exceeds Node's maximum timeout ---
  // setTimeout clamps anything above 2^31-1 ms to 1ms, so an unbounded delay
  // does not wait — it fires pump() immediately, gains no token, and re-arms,
  // spinning at 1ms forever. A rate low enough to overflow must still schedule
  // a real wait.
  {
    const MAX_TIMER_MS = 2_147_483_647;
    let clock = 0;
    const delays = [];
    const setTimer = (fn, ms) => { delays.push(ms); };
    const bucket = createTokenBucket({
      ratePerMin: 1e-5, capacity: 1, now: () => clock, setTimer,
    });

    bucket.take(() => {});   // spends the only token, runs inline, schedules nothing
    bucket.take(() => {});   // queues, so this one arms the refill timer

    const armed = delays.length === 1 && delays[0] <= MAX_TIMER_MS && delays[0] >= 1;
    if (armed) {
      pass('a tiny rate still schedules within the maximum timeout instead of clamping to 1ms');
    } else {
      fail(`refill delay out of range: ${JSON.stringify(delays)} (max ${MAX_TIMER_MS})`);
    }
  }

  // --- a throwing callback does not strand the queue ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const bucket = createTokenBucket({ ratePerMin: 60, capacity: 1, now: () => clock, setTimer });

    // Drain the bucket so the next calls queue.
    bucket.take(() => {});
    const ran = [];
    const thrower = () => { throw new Error('test error'); };
    bucket.take(thrower);         // First queued: will throw
    bucket.take(() => ran.push(1)); // Second queued
    bucket.take(() => ran.push(2)); // Third queued

    // Advance clock and fire timers. The first callback throws, but schedule()
    // must still be called (via finally block) to arm the next timer. We wrap
    // fireAll in try/catch so the error is contained and doesn't break the test.
    clock += 1_000;
    try { setTimer.fireAll(); } catch (e) { /* Expected: thrower throws. */ }

    // The thrower spent that token, so nothing else ran in the first pump.
    // Each later refill releases exactly one queued callback.
    clock += 1_000;
    try { setTimer.fireAll(); } catch (e) { /* Expected: should not throw again. */ }

    // Third callback runs in this pump.
    clock += 1_000;
    try { setTimer.fireAll(); } catch (e) { /* should not happen */ }

    if (ran.join(',') === '1,2') {
      pass('a throwing callback does not strand the queue');
    } else {
      fail(`queue stranded: ran=[${ran.join(',')}]`);
    }
  }

  const mkResolver = (result = [null, '93.184.216.34', 4]) => {
    const calls = [];
    const resolver = (hostname, opts, cb) => { calls.push({ hostname, opts, cb }); };
    resolver.calls = calls;
    resolver.flush = () => { for (const c of calls.splice(0)) c.cb(...result); };
    return resolver;
  };

  const lookupOnce = (fn, hostname, opts = {}) =>
    new Promise((resolve) => fn(hostname, opts, (...args) => resolve(args)));

  // --- distinct hostnames are metered ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const resolver = mkResolver();
    const lookup = createCachedLookup(resolver, {
      lookupsPerMin: 60, burst: 2, now: () => clock, setTimer,
    });

    for (let i = 0; i < 5; i++) lookupOnce(lookup, `h${i}.example.com`);
    const duringBurst = resolver.calls.length;

    clock += 1_000;
    setTimer.fireAll();
    const afterRefill = resolver.calls.length;
    resolver.flush();

    if (duringBurst === 2 && afterRefill === 3) {
      pass('5 distinct hostnames: 2 resolved on the burst, 1 more per refill');
    } else {
      fail(`hostname pacing wrong: duringBurst=${duringBurst} afterRefill=${afterRefill}`);
    }
  }

  // --- coalesced waiters and cache hits are free ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const resolver = mkResolver();
    const lookup = createCachedLookup(resolver, {
      lookupsPerMin: 60, burst: 1, now: () => clock, setTimer,
    });

    // 20 concurrent callers, one hostname: only the leader reaches the
    // resolver, so only the leader may spend the single available token.
    const pending = Array.from({ length: 20 }, () => lookupOnce(lookup, 'one.example.com'));
    const leaderOnly = resolver.calls.length === 1 && setTimer.pending() === 0;
    resolver.flush();
    await Promise.all(pending);

    // And a warm cache hit must not queue behind the (now empty) bucket.
    await lookupOnce(lookup, 'one.example.com');
    const hitWasFree = resolver.calls.length === 0 && setTimer.pending() === 0;

    if (leaderOnly && hitWasFree) {
      pass('coalesced waiters and cache hits take no tokens — pacing tracks distinct hostnames');
    } else {
      fail(`token accounting wrong: leaderOnly=${leaderOnly} hitWasFree=${hitWasFree}`);
    }
  }

  // --- a negative-cached refusal is free too ---
  // Guards the seam between negative caching (#2229 resolver refusals) and
  // pacing: both landed separately, so nothing covered them together. A
  // refusal held in the negative cache is answered from memory and never
  // reaches the resolver, so it must not wait on a token either — otherwise a
  // drained bucket would stall the very retry storm the negative cache exists
  // to absorb.
  {
    let clock = 0;
    const setTimer = mkTimer();
    const refusal = Object.assign(new Error('refused'), { code: 'EREFUSED' });
    const resolver = mkResolver([refusal]);
    const lookup = createCachedLookup(resolver, {
      lookupsPerMin: 60, burst: 1, now: () => clock, setTimer,
    });

    // The leader spends the only token and is refused; the refusal is cached.
    const first = lookupOnce(lookup, 'refused.example.com');
    resolver.flush();
    const [firstErr] = await first;

    // Bucket is now empty. Deliver via callback rather than await: if the hit
    // wrongly queued for a token it would never settle, and this must fail
    // rather than hang.
    let settled = false;
    let secondErr = null;
    lookup('refused.example.com', {}, (e) => { settled = true; secondErr = e; });
    await new Promise((r) => setImmediate(r));

    const free = settled && resolver.calls.length === 0 && setTimer.pending() === 0;
    if (free && firstErr?.code === 'EREFUSED' && secondErr?.code === 'EREFUSED') {
      pass('a negative-cached refusal is served without spending a pacing token');
    } else {
      fail(`negative-cache hit not free: settled=${settled} calls=${resolver.calls.length} `
        + `pending=${setTimer.pending()} first=${firstErr?.code} second=${secondErr?.code}`);
    }
  }

  // --- pacing can be switched off entirely ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const resolver = mkResolver();
    const lookup = createCachedLookup(resolver, {
      lookupsPerMin: 0, now: () => clock, setTimer,
    });

    for (let i = 0; i < 50; i++) lookupOnce(lookup, `off${i}.example.com`);
    const all = resolver.calls.length === 50 && setTimer.pending() === 0;
    resolver.flush();

    if (all) {
      pass('lookupsPerMin: 0 disables pacing — every miss goes straight to the resolver');
    } else {
      fail(`disable wrong: calls=${resolver.calls.length} timers=${setTimer.pending()}`);
    }
  }

  // --- env parsing: unset means the default, junk means the default, 0 means off ---
  {
    const seen = {
      unset: lookupsPerMinFromEnv({}),
      empty: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: '' }),
      set: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: '120' }),
      off: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: '0' }),
      junk: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: 'fast' }),
      negative: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: '-1' }),
    };

    if (seen.unset === 400 && seen.empty === 400 && seen.set === 120
        && seen.off === 0 && seen.junk === 400 && seen.negative === 400) {
      pass('CAREER_OPS_DNS_LOOKUPS_PER_MIN parses, defaults to 400, and 0 disables');
    } else {
      fail(`env parsing wrong: ${JSON.stringify(seen)}`);
    }
  }

  // --- whitespace must not read as 0 ---
  // `Number(' ')` is 0, and 0 is the documented "pacing off" value, so a
  // whitespace-only setting would silently disable the rate limiter instead of
  // being rejected like any other junk. Silent-off is the one failure this knob
  // must never have.
  {
    const seen = {
      space: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: ' ' }),
      tab: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: '\t' }),
      padded: lookupsPerMinFromEnv({ CAREER_OPS_DNS_LOOKUPS_PER_MIN: ' 120 ' }),
    };

    if (seen.space === 400 && seen.tab === 400 && seen.padded === 120) {
      pass('whitespace falls back to the default instead of silently disabling pacing');
    } else {
      fail(`whitespace handling wrong: ${JSON.stringify(seen)}`);
    }
  }

  // --- pacing is on by default, with no options passed ---
  {
    let clock = 0;
    const setTimer = mkTimer();
    const resolver = mkResolver();
    // Only the clock and timer are injected: rate and burst take their defaults.
    const lookup = createCachedLookup(resolver, { now: () => clock, setTimer });

    for (let i = 0; i < 25; i++) lookupOnce(lookup, `d${i}.example.com`);
    const admitted = resolver.calls.length;
    const queued = setTimer.pending() > 0;
    resolver.flush();

    if (admitted === 20 && queued) {
      pass('pacing defaults to on — 25 hostnames admit the 20-token burst and queue the rest');
    } else {
      fail(`default pacing wrong: admitted=${admitted} queued=${queued}`);
    }
  }
} catch (e) {
  fail(`DNS pacing tests threw: ${e.message}`);
}

// tests/providers/icims.test.mjs
import { readFileSync } from 'node:fs';
import { join } from 'path';
import { pathToFileURL } from 'url';
import { pass, fail, ROOT } from '../helpers.mjs';

console.log('\nProvider — icims');

const mod = await import(pathToFileURL(join(ROOT, 'providers/icims.mjs')).href);
const icims = mod.default;
const { parseIcimsSearchPage } = mod;

const ORIGIN = 'https://careers-acmefreight.icims.com';
const fixture = readFileSync(join(ROOT, 'tests/fixtures/icims-search-page.html'), 'utf-8');

if (icims.id === 'icims') pass('icims.id is "icims"');
else fail(`icims.id is ${JSON.stringify(icims.id)}`);

// detect(): any *.icims.com https careers_url resolves to the search URL.
{
  const hit = icims.detect({ name: 'Acme', careers_url: `${ORIGIN}/jobs/search?ss=1&in_iframe=1` });
  if (hit && hit.url === `${ORIGIN}/jobs/search?ss=1&pr=0&in_iframe=1`) pass('icims.detect() resolves portal search URL');
  else fail(`icims.detect() returned ${JSON.stringify(hit)}`);

  if (icims.detect({ name: 'X', careers_url: 'https://example.com/jobs' }) === null) pass('icims.detect() null for non-icims URL');
  else fail('icims.detect() accepted a non-icims URL');

  if (icims.detect({ name: 'X', careers_url: 'http://careers-a.icims.com/jobs' }) === null) pass('icims.detect() rejects plain http');
  else fail('icims.detect() accepted http URL');
}

// parseIcimsSearchPage(): two same-origin cards parsed; foreign-host card dropped.
{
  const jobs = parseIcimsSearchPage(fixture, ORIGIN, 'acmefreight');
  if (jobs.length === 2) pass('parses 2 same-origin job cards (foreign-host card dropped)');
  else fail(`expected 2 jobs, got ${jobs.length}: ${JSON.stringify(jobs.map(j => j.url))}`);

  const [dir, fork] = jobs;
  if (dir.title === 'Director, Revenue Operations & Strategy') pass('title extracted with entities decoded');
  else fail(`title: ${JSON.stringify(dir.title)}`);
  if (dir.url === `${ORIGIN}/jobs/1234/director%2c-revenue-operations/job`) pass('url extracted with query stripped');
  else fail(`url: ${dir.url}`);
  if (dir.location === 'US-NJ-Edison') pass('location extracted');
  else fail(`location: ${JSON.stringify(dir.location)}`);
  if (dir.company === 'acmefreight') pass('company passed through');
  else fail(`company: ${dir.company}`);
  if (dir.postedAt === undefined) pass('no postedAt on list-page jobs (enrichDate supplies it later)');
  else fail(`unexpected postedAt: ${dir.postedAt}`);
  if (fork.location === 'US-CA-Fontana' && fork.title === 'Forklift Operator') pass('second card parsed');
  else fail(`second card: ${JSON.stringify(fork)}`);
}

// Relative posting hrefs must resolve against the origin, not be dropped.
{
  const relCard = `<li class="iCIMS_JobCardItem"><div class="col-xs-12 title">
    <a href="/jobs/7777/relative-role/job?in_iframe=1" class="iCIMS_Anchor"><h3 >Relative Role</h3></a></div></li>`;
  const jobs = parseIcimsSearchPage(`<ul>${relCard}</ul>`, ORIGIN, 'acmefreight');
  if (jobs.length === 1 && jobs[0].url === `${ORIGIN}/jobs/7777/relative-role/job`) pass('relative href resolved against origin');
  else fail(`relative href: ${JSON.stringify(jobs.map(j => j.url))}`);

  // A relative href is still origin-checked once resolved — a protocol-relative
  // link to another host must not sneak past.
  const offHost = `<li class="iCIMS_JobCardItem"><div class="col-xs-12 title">
    <a href="//evil.example.com/jobs/8888/x/job" class="iCIMS_Anchor"><h3 >Off Host</h3></a></div></li>`;
  if (parseIcimsSearchPage(`<ul>${offHost}</ul>`, ORIGIN, 'acmefreight').length === 0) pass('resolved off-host href still dropped');
  else fail('off-host protocol-relative href was not dropped');
}

// Empty/garbage input → [] not a throw.
{
  if (parseIcimsSearchPage('', ORIGIN, 'x').length === 0 && parseIcimsSearchPage('<html>no cards</html>', ORIGIN, 'x').length === 0) {
    pass('empty/garbage HTML parses to []');
  } else {
    fail('garbage HTML did not parse to []');
  }
}

// ── fetch(): pagination ─────────────────────────────────────────────
const mkCard = (id, title) => `
<li class="iCIMS_JobCardItem"><div class="row">
<div class="col-xs-6 header left"><span class="sr-only field-label">Location</span><span >US-TX-Austin</span></div>
<div class="col-xs-12 title"><a href="${ORIGIN}/jobs/${id}/${title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}/job?in_iframe=1" class="iCIMS_Anchor"><h3 >${title}</h3></a></div>
</div></li>`;
const page = (...cards) => `<ul class="iCIMS_JobsTable">${cards.join('')}</ul>`;

const mkCtx = (pages) => ({
  transport: 'http',
  sleep: async () => {},
  fetchJson: async () => { throw new Error('fetchJson should not be called'); },
  fetchText: async (url) => {
    const pr = Number(new URL(url).searchParams.get('pr'));
    mkCtx.calls.push(pr);
    return pages[pr] ?? page(); // out-of-range → empty page
  },
});

// Multi-page tenant: stops on the first empty page.
{
  mkCtx.calls = [];
  const ctx = mkCtx([page(mkCard(1, 'Role A'), mkCard(2, 'Role B')), page(mkCard(3, 'Role C'))]);
  const jobs = await icims.fetch({ name: 'acmefreight', careers_url: `${ORIGIN}/jobs/search?ss=1` }, ctx);
  if (jobs.length === 3 && mkCtx.calls.join(',') === '0,1,2') pass('fetch paginates and stops on empty page');
  else fail(`jobs=${jobs.length} calls=${mkCtx.calls.join(',')}`);
}

// Tenant that repeats the last page for out-of-range pr: repeat-content stop.
{
  mkCtx.calls = [];
  const repeating = page(mkCard(9, 'Sticky Role'));
  const ctx = mkCtx({ 0: page(mkCard(1, 'First')), 1: repeating, 2: repeating, 3: repeating });
  const jobs = await icims.fetch({ name: 'acmefreight', careers_url: `${ORIGIN}/jobs/search?ss=1` }, ctx);
  if (jobs.length === 2 && mkCtx.calls.length === 3) pass('fetch stops when a page repeats the previous first URL');
  else fail(`jobs=${jobs.length} calls=${mkCtx.calls.length}`);
}

// A board that ends naturally is NOT flagged — the flag must mean "capped",
// not "finished", or the run summary cries wolf on every healthy tenant.
{
  mkCtx.calls = [];
  const ctx = mkCtx([page(mkCard(1, 'Role A')), page(mkCard(2, 'Role B'))]);
  const jobs = await icims.fetch({ name: 'acmefreight', careers_url: `${ORIGIN}/jobs/search?ss=1` }, ctx);
  if (jobs.icimsTruncated === undefined) pass('complete board carries no truncation flag');
  else fail(`complete board flagged truncated (${jobs.length} jobs)`);
}

// A board deeper than the page cap is flagged instead of silently truncated:
// every page holds distinct jobs, so neither natural stop condition fires.
{
  mkCtx.calls = [];
  const deep = {};
  for (let i = 0; i < 60; i++) deep[i] = page(mkCard(100 + i, `Role ${i}`));
  const ctx = mkCtx(deep);
  const jobs = await icims.fetch({ name: 'bigtenant', careers_url: `${ORIGIN}/jobs/search?ss=1` }, ctx);
  if (jobs.icimsTruncated === true && jobs.length === mkCtx.calls.length) {
    pass(`fetch flags truncation at the page cap (${mkCtx.calls.length} pages)`);
  } else {
    fail(`icimsTruncated=${jobs.icimsTruncated} jobs=${jobs.length} pages=${mkCtx.calls.length}`);
  }
}

// ── enrichDate(): detail-page JSON-LD ───────────────────────────────
{
  const job = { title: 'X', url: `${ORIGIN}/jobs/1234/x/job`, company: 'acmefreight', location: 'US' };
  const detail = `<html><script type="application/ld+json">{"@type":"JobPosting","datePosted":"2026-07-20","title":"X"}</script></html>`;
  await icims.enrichDate(job, { fetchText: async () => detail });
  if (job.postedAt === Date.parse('2026-07-20')) pass('enrichDate sets postedAt from JSON-LD datePosted');
  else fail(`postedAt: ${job.postedAt}`);
}
{
  const job = { title: 'X', url: `${ORIGIN}/jobs/1234/x/job`, company: 'acmefreight', location: 'US' };
  await icims.enrichDate(job, { fetchText: async () => '<html>no ldjson</html>' });
  if (job.postedAt === undefined) pass('enrichDate leaves job undated when JSON-LD missing');
  else fail(`postedAt unexpectedly set: ${job.postedAt}`);
}
// @graph document: JobPosting node nested under @graph is still found.
{
  const job = { title: 'X', url: `${ORIGIN}/jobs/1234/x/job`, company: 'acmefreight', location: 'US' };
  const detail = `<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"WebPage"},{"@type":"JobPosting","datePosted":"2026-07-18"}]}</script>`;
  await icims.enrichDate(job, { fetchText: async () => detail });
  if (job.postedAt === Date.parse('2026-07-18')) pass('enrichDate reads datePosted from an @graph JobPosting node');
  else fail(`@graph postedAt: ${job.postedAt}`);
}
// Array-form JSON-LD: pick the JobPosting element, skip the non-JobPosting one.
{
  const job = { title: 'X', url: `${ORIGIN}/jobs/1234/x/job`, company: 'acmefreight', location: 'US' };
  const detail = `<script type="application/ld+json">[{"@type":"Organization","datePosted":"2026-01-01"},{"@type":"JobPosting","datePosted":"2026-07-19"}]</script>`;
  await icims.enrichDate(job, { fetchText: async () => detail });
  if (job.postedAt === Date.parse('2026-07-19')) pass('enrichDate picks the JobPosting node from an array');
  else fail(`array postedAt: ${job.postedAt}`);
}
{
  const job = { title: 'X', url: `${ORIGIN}/jobs/1234/x/job`, company: 'acmefreight', location: 'US' };
  await icims.enrichDate(job, { fetchText: async () => '<script type="application/ld+json">{broken json</script>' });
  if (job.postedAt === undefined) pass('enrichDate tolerates malformed JSON-LD without throwing');
  else fail(`postedAt unexpectedly set: ${job.postedAt}`);
}

// ── attribute ordering must not change what we extract ──────────────
// Tenants theme their portals, so `field-label` is one token in a class list,
// not reliably the last one. A matcher anchored on `field-label">` reads an
// empty location off a card that plainly has one, and an empty location fails
// location_filter — the posting is dropped with no error to explain it.
{
  const locCard = (cls) => `<li class="iCIMS_JobCardItem"><div class="row">
    <div class="col-xs-6 header left"><span class="${cls}">Location</span><span >US-TX-Austin</span></div>
    <div class="col-xs-12 title"><a href="${ORIGIN}/jobs/4242/themed-role/job" class="iCIMS_Anchor"><h3 >Themed Role</h3></a></div>
  </div></li>`;
  for (const cls of ['field-label', 'sr-only field-label', 'field-label sr-only', 'a field-label b']) {
    const [j] = parseIcimsSearchPage(locCard(cls), ORIGIN, 'acmefreight');
    if (j && j.location === 'US-TX-Austin') pass(`location extracted with class="${cls}"`);
    else fail(`class="${cls}" → location ${JSON.stringify(j?.location)}`);
  }
}

// Same failure mode on the detail page. A tenant running Content-Security-
// Policy emits a nonce on every inline script, which pushes `type` off the
// front of the tag. If the matcher requires `type` first, enrichment finds no
// date, every posting on that board stays undated, the undated policy drops
// them, and a working board is indistinguishable from an empty one.
{
  const ld = '{"@type":"JobPosting","datePosted":"2026-07-17"}';
  const variants = {
    'a nonce before type': `<script nonce="r4nd0m" type="application/ld+json">${ld}</script>`,
    'an attribute after type': `<script type="application/ld+json" id="jobposting">${ld}</script>`,
    'a single-quoted type': `<script type='application/ld+json'>${ld}</script>`,
    'extra whitespace': `<script  type="application/ld+json" >${ld}</script>`,
  };
  for (const [label, detail] of Object.entries(variants)) {
    const job = { title: 'X', url: `${ORIGIN}/jobs/1234/x/job`, company: 'acmefreight', location: 'US' };
    await icims.enrichDate(job, { fetchText: async () => detail });
    if (job.postedAt === Date.parse('2026-07-17')) pass(`enrichDate reads JSON-LD with ${label}`);
    else fail(`JSON-LD with ${label}: postedAt ${job.postedAt}`);
  }
}

